// Field tables derived from vanilla-mcdoc (SpyglassMC, MIT; commit in data/mcdoc-subset.json "source"), resolved per
// Minecraft version: which top-level keys a recipe / loot function / pool / trigger may have, and which are required.
// `since` is inclusive and `until` exclusive, as in mcdoc. Only the subset the emitters write is in the data file
// (scripts/cyrus/datapack-derive.py); anything else resolves to null ("not checked"), never to "fine".
import subset from "./data/mcdoc-subset.json";
import { atLeast, compareMc } from "./versions";

type Field = { n?: string; opt?: boolean; since?: string; until?: string; spread?: string | Field[]; dynamic?: string };
type Dispatch = { since?: string; until?: string; alts: { since?: string; until?: string; fields: Field[] }[] };
const DATA = subset as unknown as { source: Record<string, string>; dispatch: Record<string, Dispatch>; structs: Record<string, Field[]> };

export const MCDOC_SOURCE = DATA.source;
const inRange = (v: string, x: { since?: string; until?: string }) => (!x.since || atLeast(v, x.since)) && (!x.until || compareMc(v, x.until) < 0);

export type FieldTable = { fields: Map<string, { required: boolean }>; open: boolean };

function collect(fields: Field[], v: string, out: FieldTable, depth: number): void {
  if (depth > 12) { out.open = true; return; }
  for (const f of fields) {
    if (!inRange(v, f)) continue;
    if (f.dynamic) { out.open = true; continue; }
    if (f.spread) {
      if (Array.isArray(f.spread)) collect(f.spread, v, out, depth + 1);
      else if (DATA.structs[f.spread]) collect(DATA.structs[f.spread], v, out, depth + 1);
      else out.open = true; // a spread we did not derive: cannot judge extra keys
      continue;
    }
    if (!f.n) continue;
    if (f.n === "*") { out.open = true; continue; }
    const prev = out.fields.get(f.n);
    out.fields.set(f.n, { required: !f.opt || !!prev?.required });
  }
}

/** Fields of `registry/key` (e.g. "loot_function/set_count") in version v; null = not in the subset or not in this version. */
export function dispatchFields(key: string, v: string): FieldTable | null {
  const d = DATA.dispatch[key];
  if (!d || !inRange(v, d)) return null;
  const out: FieldTable = { fields: new Map(), open: false };
  const alts = d.alts.filter((a) => inRange(v, a));
  if (!alts.length) return null;
  for (const a of alts) collect(a.fields, v, out, 0);
  return out;
}

export function structFields(name: string, v: string): FieldTable | null {
  const s = DATA.structs[name];
  if (!s) return null;
  const out: FieldTable = { fields: new Map(), open: false };
  collect(s, v, out, 0);
  return out;
}

/** Keys not allowed / required keys missing, for one JSON object. `ignore` = keys checked elsewhere (e.g. "type"). */
export function checkKeys(obj: Record<string, unknown>, t: FieldTable | null, ignore: string[] = []): { unknown: string[]; missing: string[] } {
  if (!t) return { unknown: [], missing: [] };
  const unknown = t.open ? [] : Object.keys(obj).filter((k) => !t.fields.has(k) && !ignore.includes(k));
  const missing = [...t.fields].filter(([k, f]) => f.required && !(k in obj) && !ignore.includes(k)).map(([k]) => k);
  return { unknown, missing };
}
