// Static validator for data pack FILES (what the emitters wrote, or raw JSON from an imported pack), per version:
//   mcmeta         pack.mcmeta shape (pack_format before 1.21.9, min_format/max_format after) and the registry's number
//   mcdoc_fields   top-level keys of recipes / loot tables / pools / entries / functions / conditions / advancements /
//                  criteria / enchantments against the vanilla-mcdoc field tables (./mcdoc.ts)
//   value_shapes   the format changes that break packs silently: ingredient shape (1.21.2), text in item components
//                  (1.21.5), advancement background (1.21.5), entity predicates (26.2), cooking result count (26.1)
//   vanilla_ids    recipe types, loot function / condition types, triggers, items in results and ingredients exist
//   function_safety the .mcfunction allowlist (./functions.ts)
//   not_checked    resources outside the studio's subset (worldgen, predicates, ...): listed, kept, never judged
// Pure: works on { path, text } pairs. A check that found nothing to look at is "pass" with an empty list.
import { checkFunctions } from "./functions";
import { checkKeys, dispatchFields, structFields } from "./mcdoc";
import type { CheckStatus, DpCheck } from "./spec";
import { dataPackFeatures, isVanilla, vanillaIds, type DataPackFeatures, type IdKind } from "./versions";
import { checkWorldgenFile, resolveWorldgenRefs, worldgenPath, type WgRef } from "./worldgen/files";

export const FILE_CHECKS = ["mcmeta", "mcdoc_fields", "value_shapes", "vanilla_ids", "function_safety", "not_checked"] as const;
/** `data`: binary content (structure .nbt); text files only need `text`. */
export type PackFile = { path: string; text: string; data?: Uint8Array };
export type FileReport = { ok: boolean; version: string; checks: DpCheck[]; errors: string[]; warnings: string[]; notChecked: string[] };

const isObj = (v: unknown): v is Record<string, unknown> => !!v && typeof v === "object" && !Array.isArray(v);
const COOKING = ["minecraft:smelting", "minecraft:blasting", "minecraft:smoking", "minecraft:campfire_cooking"];

/** data/<ns>/<type>/<path>.<ext> -> parts (singular folders only: the studio's floor is 1.21.1). */
export function dataPath(p: string): { ns: string; type: string; id: string; ext: string } | null {
  const m = /^data\/([a-z0-9_.-]+)\/((?:tags\/[a-z_]+)|[a-z_]+)\/([a-z0-9_./-]+)\.(json|mcfunction)$/.exec(p);
  if (!m) return null;
  return { ns: m[1], type: m[2], id: `${m[1]}:${m[3]}`, ext: m[4] };
}

/** opts.worldgen: also judge worldgen files (biomes, dimensions, features, structures, structure .nbt); otherwise they stay not_checked. */
export function validatePackFiles(files: PackFile[], version: string, opts: { worldgen?: boolean } = {}): FileReport {
  const items = new Map<string, string[]>(FILE_CHECKS.map((c) => [c, []]));
  const failed = new Set<string>();
  const errors: string[] = [], warnings: string[] = [], notChecked: string[] = [];
  const fail = (c: string, m: string) => { failed.add(c); items.get(c)!.push(m); errors.push(m); };
  const warn = (c: string, m: string) => { items.get(c)!.push(`warn ${m}`); warnings.push(m); };
  const fr = dataPackFeatures(version);
  const finish = (): FileReport => ({
    ok: errors.length === 0, version, errors, warnings, notChecked,
    checks: FILE_CHECKS.map((id) => ({ id, status: (failed.has(id) ? "fail" : items.get(id)!.length ? (id === "not_checked" ? "warn" : "warn") : "pass") as CheckStatus, items: items.get(id)!.slice(0, 20) })),
  });
  if (!fr.ok) { fail("mcmeta", fr.error); return finish(); }
  const fe = fr.features;

  const mc = files.find((f) => f.path === "pack.mcmeta");
  if (!mc) fail("mcmeta", "pack.mcmeta is missing (Minecraft ignores the pack)");
  else checkMcmeta(mc.text, fe, (m) => fail("mcmeta", m));

  const fnFiles: { id: string; commands: string[] }[] = [];
  const wgRefs: WgRef[] = [];
  const fnTags = new Map<string, string[]>();
  const nsSet = new Set<string>();
  for (const f of [...files].sort((a, b) => (a.path < b.path ? -1 : 1))) {
    if (f.path === "pack.mcmeta" || f.path === "pack.png") continue;
    const w = opts.worldgen ? worldgenPath(f.path) : null;
    if (w) { nsSet.add(w.ns); if (!checkWorldgenFile(w.type, f, f.path, version, fail, warn, wgRefs)) notChecked.push(f.path); continue; }
    const d = dataPath(f.path);
    if (!d) { notChecked.push(f.path); continue; }
    nsSet.add(d.ns);
    if (d.ext === "mcfunction") { if (d.type === "function") fnFiles.push({ id: d.id, commands: f.text.split(/\r?\n/) }); else notChecked.push(f.path); continue; }
    let j: unknown;
    try { j = JSON.parse(f.text.replace(/^\uFEFF/, "")); } catch (e) { fail("mcdoc_fields", `${f.path}: not valid JSON (${(e as Error).message.slice(0, 80)})`); continue; }
    const ctx: Ctx = { at: f.path, fe, v: version, fail, warn };
    if (d.type === "recipe") checkRecipe(j, ctx);
    else if (d.type === "loot_table") checkLoot(j, ctx);
    else if (d.type === "advancement") checkAdvancement(j, ctx);
    else if (d.type === "enchantment") checkEnchantment(j, ctx);
    else if (d.type === "damage_type" || d.type === "jukebox_song") checkFixedKeys(j, ctx, d.type);
    else if (d.type === "predicate" || d.type === "item_modifier") checkLootPieces(j, ctx, d.type);
    else if (d.type.startsWith("tags/")) {
      checkTag(j, ctx);
      if (d.type === "tags/function" && isObj(j) && Array.isArray(j.values)) fnTags.set(`#${d.id}`, j.values.filter((x): x is string => typeof x === "string" && !x.startsWith("#")));
    }
