// The build-service image must contain every module and data file the service reads at startup. A missing one
// crashes the service (require) or silently degrades prompts (data files). Pure: reads source files only.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";

const DIR = path.join(__dirname, "..", "services", "modbuilder");
const docker = fs.readFileSync(path.join(DIR, "Dockerfile"), "utf8");
const copied = new Set<string>();
for (const line of docker.split("\n")) {
  const m = /^COPY\s+--chown=\S+\s+(.+?)\s+\/opt\/mb\/app\/\s*$/.exec(line.trim());
  if (m) for (const f of m[1].split(/\s+/)) copied.add(f);
}
const jsFiles = fs.readdirSync(DIR).filter((f) => f.endsWith(".js"));

describe("build-service image contents", () => {
  it("copies every local module any service file requires", () => {
    const need = new Set<string>(["server.js"]);
    for (const f of jsFiles) {
      for (const m of fs.readFileSync(path.join(DIR, f), "utf8").matchAll(/require\("\.\/([\w.-]+)"\)/g)) need.add(m[1].endsWith(".js") ? m[1] : `${m[1]}.js`);
    }
    const missing = [...need].filter((f) => !copied.has(f));
    assert.deepEqual(missing, [], `Dockerfile COPY is missing: ${missing.join(", ")}`);
  });
  it("copies every data file read from the app directory", () => {
    const need = new Set<string>();
    for (const f of jsFiles) {
      for (const m of fs.readFileSync(path.join(DIR, f), "utf8").matchAll(/path\.join\(__dirname,\s*"([\w.-]+\.(?:json|txt))"\)/g)) need.add(m[1]);
    }
    assert.ok(need.size >= 3, "expected the example/catalog data files to be detected");
    const missing = [...need].filter((f) => !copied.has(f));
    assert.deepEqual(missing, [], `Dockerfile COPY is missing data files: ${missing.join(", ")}`);
  });
  it("copies the version registry when provided (optional glob)", () => {
    assert.match(docker, /registry\.jso\[n\]/);
  });
  it("copies every script a service file starts by path (e.g. the catalog MCP server)", () => {
    const need = new Set<string>();
    for (const f of jsFiles) {
      for (const m of fs.readFileSync(path.join(DIR, f), "utf8").matchAll(/path\.join\(__dirname,\s*"([\w.-]+\.js)"\)/g)) need.add(m[1]);
    }
    assert.ok(need.has("catalog-mcp.js"), "expected the catalog MCP server to be detected");
    const missing = [...need].filter((f) => !copied.has(f));
    assert.deepEqual(missing, [], `Dockerfile COPY is missing scripts: ${missing.join(", ")}`);
  });
  it("the deploy script copies every Dockerfile COPY source (its list is derived from the Dockerfile)", () => {
    const script = path.join(__dirname, "..", "scripts", "cyrus", "deploy-modbuilder.sh");
    const listed = new Set(execFileSync("bash", [script, "--list"], { encoding: "utf8", env: { PATH: process.env.PATH ?? "/usr/bin:/bin" } as unknown as NodeJS.ProcessEnv }).split("\n").filter(Boolean));
    const sources = new Set<string>();
    for (const line of docker.split("\n")) {
      const t = line.trim().split(/\s+/);
      if (t[0] !== "COPY") continue;
      for (const x of t.slice(1, -1)) if (!x.startsWith("--") && !x.includes("[")) sources.add(x);
    }
    assert.ok(sources.size >= 40, `expected the full COPY list, got ${sources.size}`);
    const missing = [...sources].filter((f) => !listed.has(f));
    assert.deepEqual(missing, [], `deploy-modbuilder.sh would not copy: ${missing.join(", ")}`);
    for (const f of ["run.sh", "Dockerfile", "lib:versions/registry.json", "lib:import/deps.json"]) assert.ok(listed.has(f), f);
    for (const f of sources) if (f !== "toolchain.tgz") assert.ok(fs.existsSync(path.join(DIR, f)), `COPY source ${f} is not in services/modbuilder`);
  });
});

