// Data pack specs in the build service (Cyrus R2 data pack studio). The model writes DataPackSpec files
// (assets/datapack/<name>.json: recipes, loot tables, advancements, tags, functions, enchantments as typed data);
// this module checks them like code with the validator + emitter GENERATED from lib/cyrus/datapack (./datapack-spec.js),
// for the build's exact Minecraft version, and cross-checks the plugin. The portal re-validates and emits again (the
// service is not trusted). Plain Node, no dependencies, I/O only in the workspace helpers.
const fs = require("fs");
const path = require("path");
const DP = require("./datapack-spec");

const DATAPACK_DIR = "assets/datapack";
const DATAPACK_FILE_RE = /^assets\/datapack\/[a-z][a-z0-9_]{1,31}\.json$/;
const MAX_DATAPACK_FILES = DP.DATAPACK_LIMITS.maxFiles;

function listDatapackFiles(ws) {
  const dir = path.join(ws, DATAPACK_DIR);
  let names = [];
  try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { return []; }
  return names.filter((e) => e.isFile()).map((e) => `${DATAPACK_DIR}/${e.name}`).filter((rel) => DATAPACK_FILE_RE.test(rel)).sort()
    .map((rel) => ({ rel, abs: path.join(ws, rel), size: fs.statSync(path.join(ws, rel)).size }));
}
function snapshotDatapackSpecs(ws) {
  const out = new Map();
  for (const f of listDatapackFiles(ws)) out.set(f.rel, fs.readFileSync(f.abs));
  return out;
}

/** The single nx_ namespace the workspace's data pack specs use (kept specs of a change build), or null. */
function namespaceOfSpecs(ws) {
  const found = new Set();
  for (const f of listDatapackFiles(ws)) { try { for (const m of fs.readFileSync(f.abs, "utf8").match(/\bnx_[a-z0-9]{8}(?=:)/g) || []) found.add(m); } catch { /* unreadable: no namespace */ } }
  return found.size === 1 ? [...found][0] : null;
}

/** Does this version have a data pack emitter (registry format + generated vanilla ids)? */
function datapackVersionOk(mcVersion) { return DP.dataPackFeatures(String(mcVersion)).ok; }
/** Cyrus R4: does this version have verified world generation data (DataVersion, noise ranges, block states)? */
function worldgenVersionOk(mcVersion) { return DP.worldgenFeatures(String(mcVersion)).ok; }

/**
 * Validate every data pack spec in the workspace (same contract as checkWorkspaceTextures / checkWorkspaceSounds):
 *   problems (HARD): invalid JSON / spec, file name != name, a resource defined twice across files, the emitted pack
 *     failing the static checks for this version, a function command off the allowlist. Dropped after the bounded
 *     repairs, never shipped.
 *   soft: a plugin that references this pack's functions / loot tables should use the reserved namespace; one repair, then warnings.
 */
function checkWorkspaceDatapacks(ws, { namespace, mcVersion, javaFiles = [], worldgen = false }) {
  const files = listDatapackFiles(ws);
  const results = [];
  const problems = [];
  const soft = [];
  if (files.length > MAX_DATAPACK_FILES) problems.push(`${files.length} data pack spec files; the limit is ${MAX_DATAPACK_FILES}. Put more resources in one spec instead.`);
  const owners = new Map(); // "type:id" -> file
  for (const f of files.slice(0, MAX_DATAPACK_FILES)) {
    const want = path.basename(f.rel, ".json");
    const r = { rel: f.rel, name: want, ok: false, problems: [] };
    results.push(r);
    if (f.size > DP.DATAPACK_LIMITS.maxSpecBytes) { r.problems.push(`${f.rel} is larger than ${DP.DATAPACK_LIMITS.maxSpecBytes / 1024} KB`); continue; }
    let json;
    try { json = JSON.parse(fs.readFileSync(f.abs, "utf8")); } catch (e) { r.problems.push(`${f.rel} is not valid JSON: ${String(e.message).slice(0, 160)}`); continue; }
    const b = DP.buildDataPack(json, { version: String(mcVersion), namespace, worldgen: worldgen === true });
    if (!b.ok) { for (const e of b.errors.slice(0, 12)) r.problems.push(`${f.rel}: ${e}`); continue; }
    if (b.pack.name !== want) { r.problems.push(`${f.rel}: "name" is "${b.pack.name}" but the file is ${want}.json; they must match`); continue; }
    const spec = b.pack.spec; // parsed (defaults applied): the same form the portal hashes
    for (const res of spec.resources) {
      const key = res.type === "tag" ? `tag/${res.registry}:${res.id}` : `${res.type}:${res.id}`;
      if (owners.has(key) && !(res.type === "tag" && String(res.id).startsWith("minecraft:"))) r.problems.push(`${f.rel}: ${res.type} ${res.id} is also defined in ${owners.get(key)}`);
      else owners.set(key, f.rel);
    }
    r.pack = b.pack; r.spec = spec;
    r.sha256 = b.pack.specSha256;
    r.warnings = b.pack.warnings;
  }
  if (files.length && javaFiles.length) {
    let text = "";
    for (const jf of javaFiles) { try { text += fs.readFileSync(jf.abs, "utf8") + "\n"; } catch { /* gone */ } }
    const foreign = [...new Set((text.match(/\bnx_[a-z0-9]{8}\b/g) || []).filter((x) => x !== namespace))];
    if (foreign.length) soft.push(`The plugin uses the namespace ${foreign.join(", ")}; this mod's reserved namespace is ${namespace}. Data pack ids are "${namespace}:<path>".`);
    if (/dispatchCommand\s*\([^)]*"(?:minecraft:)?reload/.test(text)) soft.push("The plugin runs /reload. Never reload from a plugin: Nxeon installs and reloads the data pack.");
