    if (worldgen && /new\s+WorldCreator\s*\(/.test(text)) soft.push("The plugin creates a world with WorldCreator. The data pack's dimension is created by Minecraft on the restart after install; teleport into it with Bukkit.getWorld(new NamespacedKey(...)) and handle it being absent.");
  }
  for (const r of results) { r.ok = r.problems.length === 0; problems.push(...r.problems); }
  return { files, results, problems: [...new Set(problems)], soft: [...new Set(soft)].slice(0, 20) };
}

