#!/usr/bin/env node
"use strict";
// Fetches (at IMAGE BUILD time, like tools/fetch-import-deps.js) the Spyglass (MIT) data the offline datapack /
// resource-pack validator needs, verifies every file against the sha256 pinned in spyglass-data.json, and writes
// it to <outDir>. Runtime builds never touch the network.
//   node fetch-spyglass-data.js <manifest.json> <outDir>          fetch + verify (exit 1 on any mismatch)
//   node fetch-spyglass-data.js <manifest.json> <outDir> --pin    fetch and (re)write the pinned hashes into the manifest
// Layout in outDir: vanilla-mcdoc.tar.gz, <version>/{block_states.json,commands.json,registries.json,vanilla-data.tar.gz,vanilla-assets-tiny.tar.gz}
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const BASE = "https://api.spyglassmc.com";
const FILES = {
  "block_states.json": (v) => `${BASE}/mcje/versions/${encodeURIComponent(v)}/block_states`,
  "commands.json": (v) => `${BASE}/mcje/versions/${encodeURIComponent(v)}/commands`,
  "registries.json": (v) => `${BASE}/mcje/versions/${encodeURIComponent(v)}/registries`,
  "vanilla-data.tar.gz": (v) => `${BASE}/mcje/versions/${encodeURIComponent(v)}/vanilla-data/tarball`,
  "vanilla-assets-tiny.tar.gz": (v) => `${BASE}/mcje/versions/${encodeURIComponent(v)}/vanilla-assets-tiny/tarball`,
};
const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");

async function get(url) {
  for (let i = 0; i < 3; i++) {
    try {
      const r = await fetch(url, { redirect: "follow", headers: { "user-agent": "nxeon-modbuilder-image-build" } });
      if (!r.ok) throw new Error(`${r.status} ${r.statusText}`);
      return Buffer.from(await r.arrayBuffer());
    } catch (e) { if (i === 2) throw new Error(`${url}: ${e.message}`); await new Promise((r) => setTimeout(r, 1000 * (i + 1))); }
  }
}

async function main() {
  const [manifestPath, outDir, flag] = process.argv.slice(2);
  if (!manifestPath || !outDir) { console.error("usage: fetch-spyglass-data.js <manifest.json> <outDir> [--pin]"); process.exit(2); }
  const pin = flag === "--pin";
  const m = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
  const bad = [];
  const one = async (rel, url, want, setHash) => {
    const dest = path.join(outDir, rel);
    fs.mkdirSync(path.dirname(dest), { recursive: true });
    const buf = await get(url);
    const got = sha256(buf);
    if (pin) setHash(got);
    else if (got !== want) { bad.push(`${rel}: sha256 ${got} != pinned ${want}`); return; }
    fs.writeFileSync(dest, buf);
  };
  await one("vanilla-mcdoc.tar.gz", `${BASE}/vanilla-mcdoc/tarball`, m.mcdoc.sha256, (h) => { m.mcdoc.sha256 = h; });
  for (const [v, ent] of Object.entries(m.versions)) {
    for (const [name, mk] of Object.entries(FILES)) {
      await one(`${v}/${name}`, mk(v), ent.files?.[name], (h) => { ent.files = { ...(ent.files || {}), [name]: h }; });
    }
  }
  if (pin) { fs.writeFileSync(manifestPath, JSON.stringify(m, null, 2) + "\n"); console.log("pinned", manifestPath); return; }
  if (bad.length) { console.error("spyglass data checksum mismatch:\n" + bad.join("\n")); process.exit(1); }
  console.log(`spyglass data ok: ${Object.keys(m.versions).join(" ")}`);
}
main().catch((e) => { console.error(e.message); process.exit(1); });
EOF
