cd /tank/dev-worktrees/cyrus-engine2/services/modbuilder; cat > spyglass-check.mjs <<'EOF'
// Headless, OFFLINE datapack / resource-pack checker built on SpyglassMC (MIT): @spyglassmc/core + java-edition + mcdoc,
// driven by the pinned data from spyglass-data.json (tools/fetch-spyglass-data.js). Runs as a child process
// (spyglass.js) so a crash or timeout never reaches the build service. Reads files only; writes nothing but its temp cache.
//   node spyglass-check.mjs <dataDir> <mcVersion> <packRoot> [--manifest FILE]
// stdout: one JSON line { ok, version, files, diagnostics: [{file,severity,line,col,message,rule}], ms }.
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import url from "node:url";
import { Project, fileUtil } from "@spyglassmc/core";
import { NodeJsExternals } from "@spyglassmc/core/lib/nodejs.js";
import * as je from "@spyglassmc/java-edition";
import { initialize as mcdocInit } from "@spyglassmc/mcdoc";

const argv = process.argv.slice(2);
const mi = argv.indexOf("--manifest");
const manifestFile = mi >= 0 ? argv.splice(mi, 2)[1] : path.join(path.dirname(url.fileURLToPath(import.meta.url)), "spyglass-data.json");
const [dataDir, version, packRoot] = argv;
if (!dataDir || !version || !packRoot) { console.error("usage: spyglass-check.mjs <dataDir> <mcVersion> <packRoot>"); process.exit(2); }
const t0 = Date.now();
const manifest = JSON.parse(fs.readFileSync(manifestFile, "utf8"));
if (!manifest.versions[version]) { console.log(JSON.stringify({ ok: false, unsupported: true, version, error: `no pinned Spyglass data for ${version}`, diagnostics: [] })); process.exit(0); }

// Offline: every api.spyglassmc.com request is answered from the pinned local files; anything else is a 404.
const miss = [];
globalThis.fetch = async (input) => {
  const u = new URL(typeof input === "string" ? input : input.url);
  let f = null;
  if (u.hostname === "api.spyglassmc.com") {
    const m = /^\/mcje\/versions\/([^/]+)\/(block_states|commands|registries|vanilla-data\/tarball|vanilla-assets-tiny\/tarball)$/.exec(u.pathname);
    if (u.pathname === "/mcje/versions") {
      return new Response(JSON.stringify(manifest.versionEntries), { status: 200, headers: { "content-type": "application/json", etag: "pinned" } });
    }
    if (m) f = path.join(dataDir, decodeURIComponent(m[1]), m[2].includes("/") ? `${m[2].split("/")[0]}.tar.gz` : `${m[2]}.json`);
    else if (u.pathname === "/vanilla-mcdoc/tarball") f = path.join(dataDir, "vanilla-mcdoc.tar.gz");
  }
  if (f && fs.existsSync(f)) return new Response(fs.readFileSync(f), { status: 200, headers: { etag: "pinned" } });
  miss.push(u.href);
  return new Response("not available offline", { status: 404 });
};

const SEV = { 0: "hint", 1: "info", 2: "warning", 3: "error" };
const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => (e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]));
const cacheDir = fs.mkdtempSync(path.join(os.tmpdir(), "nx-spyglass-"));
const quiet = { log() {}, info() {}, warn() {}, error() {} };
let exit = 0;
try {
  const root = fileUtil.ensureEndingSlash(url.pathToFileURL(path.resolve(packRoot)).href);
  const project = new Project({
    cacheRoot: fileUtil.ensureEndingSlash(url.pathToFileURL(cacheDir).href),
    externals: NodeJsExternals, logger: quiet, projectRoots: [root],
    defaultConfig: { env: { gameVersion: version } },
    initializers: [mcdocInit, je.initialize],
  });
  await project.init();
  await project.ready();
  const files = walk(path.resolve(packRoot)).sort();
  const texts = new Map();
  const uris = [];
  for (const f of files) {
    const lang = f.endsWith(".mcfunction") ? "mcfunction" : f.endsWith(".json") || f.endsWith(".mcmeta") ? "json" : null;
    if (!lang) continue;
    const uri = url.pathToFileURL(f).href;
    const text = fs.readFileSync(f, "utf8");
    texts.set(uri, text); uris.push(uri);
    await project.onDidOpen(uri, lang, 1, text);
  }
  const diagnostics = [];
  for (const uri of uris) {
    const r = await project.ensureClientManagedChecked(uri);
    const node = r?.node;
    const text = texts.get(uri);
    const errs = [...(node?.parserErrors ?? []), ...(node?.binderErrors ?? []), ...(node?.checkerErrors ?? []), ...(node?.linterErrors ?? [])];
    for (const e of errs) {
      const before = text.slice(0, e.range?.start ?? 0);
      const line = before.split("\n").length;
      diagnostics.push({ file: uri.slice(root.length), severity: SEV[e.severity] ?? "info", line, col: (e.range?.start ?? 0) - before.lastIndexOf("\n"), message: String(e.message).slice(0, 400), ...(e.info?.codeAction ? {} : {}) });
    }
  }
  await project.close();
  const hasErr = diagnostics.some((d) => d.severity === "error");
  console.log(JSON.stringify({ ok: !hasErr, version, files: uris.length, diagnostics, offlineMisses: miss.filter((x) => !/vanilla-assets-tiny|raw\.githubusercontent|github/.test(x)).length, ms: Date.now() - t0 }));
} catch (e) {
  console.log(JSON.stringify({ ok: false, crashed: true, version, error: String(e && e.message || e).slice(0, 300), diagnostics: [] }));
  exit = 0;
} finally {
  fs.rmSync(cacheDir, { recursive: true, force: true });
}
process.exit(exit);
EOF
