    }
  }
  await project.close();
  const hasErr = diagnostics.some((d) => d.severity === "error");
  console.log(JSON.stringify({ ok: !hasErr, version, files: uris.length, diagnostics, offlineMisses: miss.filter((x) => !/vanilla-assets-tiny|raw\.githubusercontent|github/.test(x)).length, ms: Date.now() - t0 }));
} catch (e) {
  console.log(JSON.stringify({ ok: false, crashed: true, version, error: String(e && e.message || e).slice(0, 300), diagnostics: [] }));
  exit = 0;
} finally {
  fs.rmSync(cacheDir, { recursive: true, force: true });
}
process.exit(exit);
