"use strict";
// Second-opinion data pack / resource pack validator: SpyglassMC (MIT) run headless and OFFLINE in a child process
// (spyglass-check.mjs) against the pinned data in spyglass-data.json. It is version aware (the build's exact Minecraft
// version) and reports real schema errors in recipes, loot tables, advancements, predicates, functions and worldgen JSON,
// each with a fixer hint the repair loop can act on. The in-house static checks (datapack-spec.js) stay the first line;
// this is the "what would Minecraft's own schema say" line. Flag-guarded:
//   MB_SPYGLASS=off (default) | warn (diagnostics become warnings, never drop a pack) | enforce (errors are problems)
//   MB_SPYGLASS_DIR   pinned data dir (default /opt/mb/spyglass, written at image build by tools/fetch-spyglass-data.js)
//   MB_SPYGLASS_CACHE persistent Spyglass symbol cache (speeds repeat runs ~40%); default: throw-away temp dir
//   MB_SPYGLASS_TIMEOUT_MS (default 90000)
// Anything that cannot run (flag off, module/data missing, version not pinned, timeout, crash) is "skipped" with a
// reason and NEVER a pass: callers must not count a skip as a clean result.
const fs = require("fs");
const os = require("os");
const path = require("path");
const { spawnSync } = require("child_process");

const SCRIPT = path.join(__dirname, "spyglass-check.mjs");
const MANIFEST = path.join(__dirname, "spyglass-data.json");

function mode(env = process.env) {
  const m = String(env.MB_SPYGLASS || "off").toLowerCase();
  return m === "warn" || m === "enforce" ? m : "off";
}
function dataDir(env = process.env) { return env.MB_SPYGLASS_DIR || "/opt/mb/spyglass"; }
function pinnedVersions() { try { return Object.keys(JSON.parse(fs.readFileSync(MANIFEST, "utf8")).versions); } catch { return []; } }

/** { ok, reason } : can a check run for this version in this environment? */
function ready(version, env = process.env) {
  if (!fs.existsSync(SCRIPT) || !fs.existsSync(MANIFEST)) return { ok: false, reason: "spyglass-check.mjs / spyglass-data.json missing" };
  if (!pinnedVersions().includes(String(version))) return { ok: false, reason: `Minecraft ${version} has no pinned Spyglass data` };
  try { require.resolve("@spyglassmc/core", { paths: [__dirname] }); } catch { return { ok: false, reason: "@spyglassmc/core is not installed" }; }
  if (!fs.existsSync(path.join(dataDir(env), version, "registries.json")) || !fs.existsSync(path.join(dataDir(env), "vanilla-mcdoc.tar.gz"))) return { ok: false, reason: `Spyglass data for ${version} not found in ${dataDir(env)}` };
  return { ok: true };
}

// ---- fixer hints: turn a Spyglass message into the repair instruction the model needs --------------------------------
const RULES = [
  [/^Unknown key [“"]([^”"]+)[”"]/, (m, f, v) => `Remove or rename the key "${m[1]}": it is not a field of this object in Minecraft ${v}. Check ${f} against the ${v} format (fields were renamed in 1.20.5 / 1.21.2 / 1.21.5 / 1.21.9 / 26.x).`],
  [/^Missing key [“"]([^”"]+)[”"]/, (m, f, v) => `Add the required key "${m[1]}" to this object (required in Minecraft ${v}). Recipes use result.id since 1.20.5; loot entries need "type"; advancements need "criteria".`],
  [/^Cannot find (item|block|entity_type|enchantment|mob_effect|attribute|particle_type|sound_event|loot_table|recipe|advancement|function|tag\/[a-z_]+|[a-z_/]+) [“"]([^”"]+)[”"]/, (m, f, v) => `"${m[2]}" is not a ${m[1]} in Minecraft ${v}. Use a vanilla id that exists in ${v}, or define it in your own namespace first; ids from newer versions fail here.`],
  [/^Expected [“"](advancement|attribute|ban)/, (m, f) => `${f}: this line is not a valid Minecraft command. A .mcfunction line is one command without a leading slash; use only commands that exist in this version.`],
  [/^Trailing data encountered/, (m, f) => `${f}: extra text after a complete command. Put one command per line and remove stray words or arguments.`],
  [/^Unexpected (?:token|character)/, (m, f) => `${f}: JSON syntax problem (comma, quote or bracket). Emit strictly valid JSON.`],
  [/^Expected [“"]?(?:an? )?(?:string|number|boolean|object|array|integer|list|compound)/i, (m, f, v) => `${f}: wrong value type for a field in Minecraft ${v}. Text components are objects/strings since 1.21.5; ingredients are plain id strings or tags since 1.21.2.`],
  [/^Invalid (?:enum|identifier|resource location)/, (m, f) => `${f}: not an allowed value; use lowercase ids "namespace:path" with [a-z0-9_./-] only.`],
  [/^The value .* (?:is out of range|must be)/, (m, f) => `${f}: value outside the allowed range for this field.`],
];
function hintFor(message, file, version) {
  for (const [re, fn] of RULES) { const m = re.exec(message); if (m) return fn(m, file, version); }
  return `Check ${file} against the Minecraft ${version} format for this resource type.`;
}

function mapSource(file, sourceMap) {
  // an emitted pack file back to the spec file that produced it (best effort: the spec owner of "data/<ns>/<type>/<id>")
  return (sourceMap && sourceMap[file]) || null;
}

/**
 * files: [{ path, text }] (the pack as emitted: pack.mcmeta + data/** [+ assets/**]); several packs may be merged.
 * Returns { ran, mode, version, skippedReason?, ok, errors:[...], warnings:[...], ms }.
 * errors/warnings: { file, line, col, message, hint, specFile? }
 */
function checkPackFiles(files, version, opts = {}) {
  const env = opts.env || process.env;
  const md = opts.mode || mode(env);
  const out = { ran: false, mode: md, version: String(version), ok: null, errors: [], warnings: [], ms: 0 };
  if (md === "off") { out.skippedReason = "MB_SPYGLASS=off"; return out; }
  const r = ready(version, env);
  if (!r.ok) { out.skippedReason = r.reason; return out; }
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "nx-sgpack-"));
  try {
    for (const f of files) {
      const p = path.join(tmp, f.path);
      if (!path.resolve(p).startsWith(tmp + path.sep)) continue; // never write outside the temp dir
      fs.mkdirSync(path.dirname(p), { recursive: true });
      fs.writeFileSync(p, f.data ? Buffer.from(f.data) : f.text);
    }
    const t0 = Date.now();
    const res = spawnSync(process.execPath, [SCRIPT, dataDir(env), String(version), tmp, "--manifest", MANIFEST], {
      encoding: "utf8", timeout: Number(env.MB_SPYGLASS_TIMEOUT_MS) || 90_000, maxBuffer: 16 * 1024 * 1024,
      env: { PATH: process.env.PATH, HOME: process.env.HOME, TMPDIR: process.env.TMPDIR, ...(env.MB_SPYGLASS_CACHE ? { MB_SPYGLASS_CACHE: env.MB_SPYGLASS_CACHE } : {}) },
    });
    out.ms = Date.now() - t0;
    if (res.error || res.status !== 0) { out.skippedReason = `spyglass child failed: ${res.error ? res.error.message : `exit ${res.status}`}`.slice(0, 200); return out; }
    let j;
    try { j = JSON.parse(String(res.stdout).trim().split("\n").pop()); } catch { out.skippedReason = "spyglass child returned no JSON"; return out; }
    if (j.crashed || j.unsupported) { out.skippedReason = `spyglass: ${j.error}`.slice(0, 200); return out; }
    out.ran = true;
    for (const d of j.diagnostics || []) {
      if (d.severity !== "error" && d.severity !== "warning") continue;
      const item = { file: d.file, line: d.line, col: d.col, message: d.message.length > 220 ? `${d.message.slice(0, 217)}...` : d.message, hint: hintFor(d.message, d.file, version), severity: d.severity };
      const s = mapSource(d.file, opts.sourceMap); if (s) item.specFile = s;
      (d.severity === "error" ? out.errors : out.warnings).push(item);
    }
    out.ok = out.errors.length === 0;
    return out;
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
}

/** One repair line per diagnostic, for the model's repair prompt (bounded). */
function repairLines(report, max = 12) {
  return [...report.errors, ...report.warnings].slice(0, max).map((d) => `${d.specFile ? `${d.specFile} -> ` : ""}${d.file}:${d.line}: ${d.message} | Fix: ${d.hint}`);
}

module.exports = { mode, dataDir, pinnedVersions, ready, hintFor, checkPackFiles, repairLines, SCRIPT, MANIFEST };
EOF

